      "artifactHtml": "\n<div class=\"artifact-template\">\n  <h3>Note d’assujettissement TVA — modèle à produire</h3>\n  <p><strong>Client:</strong> …</p>\n  <p><strong>Période analysée:</strong> …</p>\n  <p><strong>Type d’entité:</strong> indépendant / Sàrl / SA / association / autre</p>\n  <p><strong>Recettes analysées:</strong> ventes CH, ventes étranger, prestations exclues, dons/subventions, autres.</p>\n  <p><strong>Calcul CA déterminant:</strong> …</p>\n  <p><strong>Seuil applicable:</strong> CHF 100’000 / CHF 250’000 / cas spécial.</p>\n  <p><strong>Conclusion:</strong> inscription obligatoire / surveillance / volontaire / revue senior.</p>\n  <p><strong>Actions:</strong> questionnaire AFC, paramétrage TVA, méthode de décompte, facturation, échéances.</p>\n</div>\n",
